select 
from wo_delay_request r
join wo_order o on o.id = r.order_id and o.del_flag = '0'
left join sys_user u on u.user_id = o.applicant_id
left join sys_dept d on d.dept_id = o.applicant_dept_id

    and r.order_id = #{orderId}
    and r.engineer_id = #{applicantId}
    and r.status = #{requestStatus}

        and r.status = #{status}


        and (r.order_no like concat('%', #{keyword}, '%')
          or r.order_title like concat('%', #{keyword}, '%')
          or r.engineer_name like concat('%', #{keyword}, '%'))

    ${params.dataScope}

order by r.create_time desc, r.id desc

mapper.update:
update wo_attachment
set order_id = #{orderId}, biz_ref_id = #{requestId}
where uploader_id = #{uploaderId} and order_id is null and biz_ref_id is null
  and biz_stage = 'DELAY' and del_flag = '0'
  and id in
#{id}

update wo_order
set delay_pending_flag = '1', version = version + 1,
    update_by = #{updateBy}, update_time = #{actionTime}
where id = #{orderId} and status = 'PROCESSING' and version = #{version}
  and delay_pending_flag = '0' and del_flag = '0'

update wo_order
set extension_deadline = #{requestedDeadline}, delay_pending_flag = '0', version = version + 1,
    update_by = #{updateBy}, update_time = #{actionTime}
where id = #{orderId} and status = 'PROCESSING' and version = #{version}
  and delay_pending_flag = '1' and del_flag = '0'

update wo_order
set delay_pending_flag = '0', version = version + 1,
    update_by = #{updateBy}, update_time = #{actionTime}
where id = #{orderId} and version = #{version}
  and delay_pending_flag = '1' and del_flag = '0'
